}

func Wrap5[A, B, C, D, E, R any](f func(A, B, C, D, E) R) Value {
	return Func5(func(a, b, c, d, e Value) Value {
		return Box(f(Unbox[A](a), Unbox[B](b), Unbox[C](c), Unbox[D](d), Unbox[E](e)))
