#!/usr/bin/env python3
"""Independently recompute all 37 ratios from three retained process minima."""
from pathlib import Path
import hashlib,json,math,statistics
W=Path(__file__).resolve().parents[2]
r=json.loads((W/'campaign/results.json').read_text())
c=r['frozen_reference']['c37_times_us']
expected={}
for side in ['before','after']:
 core=r['core_campaign'][side]
 names=list(r['primary_times_us'][side])
 t={name:statistics.median(row['times_us'][i] for row in core['process_runs']) for i,name in enumerate(names)}
 for name,row in r['all_campaign']['all_tests'].items():
  if name not in t:t[name]=statistics.median(row['samples_us'][side])
 assert len(t)==len(c)==37 and set(t)==set(c)
 assert t==r['matched37_times_us'][side]
 ratios=[t[n]/c[n] for n in t]
 expected[side]={'total':sum(t.values())/sum(c.values()),'arithmetic':statistics.fmean(ratios),'median':statistics.median(ratios),'geometric':math.exp(statistics.fmean(math.log(x) for x in ratios))}
 for key,value in expected[side].items():assert math.isclose(value,r['aggregates'][side][key],rel_tol=1e-12)
 assert math.isclose(sum(t.values())/1000,r['matched37_total_ms'][side],rel_tol=1e-12)
assert math.isclose(sum(c.values())/1000,8.777346938669927,rel_tol=1e-12)
x={'status':'passed','cases':37,'method':'Independent computation from frozen C37 and medians of three retained process minima per case; tolerance 1e-12 relative.','aggregates':expected,'c_total_ms':sum(c.values())/1000,'campaign_sha256':hashlib.sha256((W/'campaign/results.json').read_bytes()).hexdigest()}
(W/'proofs/independent-metrics-check.json').write_text(json.dumps(x,indent=2)+'\n')
print(json.dumps(x,indent=2))

