"""Inspect activation in the actual generated checksum; these counts are not runtime allocation measures."""
import hashlib,re

def function_body(text,name):
 if isinstance(text,bytes):text=text.decode()
 start=text.index('func '+name+'(');opening=text.index('{',start);depth=0
 pattern=r'"(?:\\.|[^"\\])*"|`[^`]*`|\'(?:\\.|[^\'\\])*\'|//[^\n]*|/\*[\s\S]*?\*/|[{}]'
 for token in re.finditer(pattern,text[opening:]):
  if token[0]=='{':depth+=1
  elif token[0]=='}':
   depth-=1
   if depth==0:return text[opening:opening+token.end()]
 raise ValueError('Unterminated function '+name)

def checksum_shape(text):
 if isinstance(text,bytes):text=text.decode()
 result={}
 for label,name in [('getter','Get_Bench_StringFixtures_checksum'),('worker','Call_Bench_StringFixtures_checksum')]:
  if 'func '+name+'(' not in text:continue
  body=function_body(text,name)
  result[label]={'sha256':hashlib.sha256(body.encode()).hexdigest(),'direct_decoder': 'DecodeStringCodePoint' in body,
    'array_conversion': 'toCodePointArray' in body,'generic_array_fold': 'foldlArray' in body,
    'make_occurrences':len(re.findall(r'\bmake\(',body)),'body':body}
 assert result and any(row['direct_decoder'] for row in result.values()), 'String checksum rewrite did not activate'
 assert all(not row['array_conversion'] and not row['generic_array_fold'] for row in result.values()), 'Generic array path remains in optimized checksum'
 return result

