#!/usr/bin/env python3
"""Execute unchanged string actions with opaque runtime inputs; keep JS and native-only domains separate."""
import argparse
import collections
import difflib
import hashlib
import json
import os
from pathlib import Path
import re
import subprocess

def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def callback_adapter(sources):
    matches=[]
    for path,text in sources.items():
        if 'func Bench_MeasureBatch_runEffectWorker(' not in text:continue
        worker=text.split('func Bench_MeasureBatch_runEffectWorker(',1)[1]
        match=re.search(r'\bgo_arg2\s*:=\s*(.*?)\n\s*go_action\s*:=\s*Bench_MeasureBatch\(go_arg0,\s*go_arg1,\s*go_arg2\)',worker,re.S)
        assert match,'Cannot identify generated measurement callback conversion'
        aliases=re.findall(r'\b([A-Za-z_][A-Za-z0-9_]*)\s+"gopurs/output/gopurs_runtime"',text)
        assert len(aliases)==1
        expression=re.sub(r'\b'+re.escape(aliases[0])+r'\.','r.',match[1].strip())
        matches.append({'source':'func convertCallback(arg2 r.Value) func() int {\n go_arg2 := '+expression+'\n return go_arg2\n}\n','generated_source':str(path),'generated_sha256':digest(path)})
    assert len(matches)==1
    return matches[0]

def units(text):
    data = text.encode('utf-16-le', 'surrogatepass')
    return [int.from_bytes(data[i:i+2], 'little') for i in range(0, len(data), 2)]

def encoded(values, canonical):
    if canonical:
        raw = b''.join(v.to_bytes(2, 'little') for v in values).decode('utf-16-le', 'surrogatepass')
    else:
        raw = ''.join(chr(v) for v in values)
    return raw.encode('utf-8', 'surrogatepass').hex()

def corpus():
    cases = [[], [0], units('abc'), units('é€\uffff'), units('😀\U0010ffff'), [0xd800], [0xdc00],
             [0xd800, 0xdc00], [0xdc00, 0xd800], [0xd800, 97, 0xdc00], [0xd800, 0xd801, 0xdc00],
             units('a,😀,,é,'), units(',a,,b,'), [0xd800,44,0xdc00], units('a😀é') * 17,
             units('a😀é') * 1000, units('\U0010ffff') * 3000]
    records = []
    def add(kind, domain='js-utf16', **values):
        records.append({'id':len(records), 'kind':kind, 'domain':domain, **values})
    for value in cases:
        for raw in dict.fromkeys([encoded(value, True), encoded(value, False)]):
            add('checksum', text_hex=raw, units=value)
            for count in [-1,0,1,2,3,1500,len(value)+1]:
                add('take', text_hex=raw, units=value, count=count)
            for separator in [',','a','absent']:
                add('split', text_hex=raw, units=value, separator_hex=separator.encode().hex(), separator_units=units(separator))
    fragments = [[], [units('')], [units('a'),units('bc')], [[0xd800],[0xdc00]], [[0xd800],[],[0xdc00]],
                 [[0xdc00],[0xd800]], [[0xd800],units('x'),[0xdc00]], [units('😀'),units('é'),units('\0')],
                 [units('ab')]*1000, [units('\U0010ffff')]*3000]
    for values in fragments:
        for canonical in [True,False]:
            add('concat', fragments=[encoded(x,canonical) for x in values], fragment_units=values)
    malformed=['80','bf','c0af','c1bf','e080af','eda080','edb080','eda080edb080','ed9fbf','edc080',
               'e2','e282','f0','f09f','f09f98','f4908080','f5808080','ff','61ff62','efbfbd','e282ac80']
    for raw in malformed:
        add('checksum',domain='native-bytes',text_hex=raw)
        for count in [0,1,2,100]:
            add('take',domain='native-bytes',text_hex=raw,count=count)
    # Empty separators split Go runes; byte patterns can bisect a UTF-8 scalar.
    # These are historical FFI behaviors, not claims of JS conformance.
    for raw in [encoded(units('a😀é'),True),encoded([0xd800,0xdc00],False),'61ff62','']:
        for separator in ['', '9f','eda0','80']:
            add('split',domain='native-split-legacy',text_hex=raw,separator_hex=separator)
    return records

def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('build',type=Path)
    parser.add_argument('proof',type=Path)
    args=parser.parse_args()
    output=(args.build/'output').resolve(); proof=args.proof.resolve();proof.mkdir(parents=True,exist_ok=False)
    inputs=corpus();(proof/'inputs.json').write_text(json.dumps(inputs,indent=2)+'\n')
    sources={p:p.read_text() for p in (output/'purescript').rglob('*.go')}
    source_hashes={str(p):digest(p) for p in sources}
    opaque=[(p,text) for p,text in sources.items() if 'func opaqueValue(a interface{}) interface{}' in text]
    assert len(opaque)==1
    original,text=opaque[0]
    rewritten,n=re.subn(r'func opaqueValue\(a interface\{\}\) interface\{\} \{\s*return a\s*\}', '''func opaqueValue(a interface{}) interface{} {
 if StringChecksumAuditCalls>=len(StringChecksumAuditInputs){panic("unexpected opaque call")}
 value:=StringChecksumAuditInputs[StringChecksumAuditCalls];StringChecksumAuditCalls++
 if value==nil{return a};return value
}''',text)
    assert n==1
    rewritten+='\nvar StringChecksumAuditInputs []interface{}\nvar StringChecksumAuditCalls int\n'
    override=proof/'opaque-override.go';override.write_text(rewritten)
    (proof/'opaque-override.patch').write_text(''.join(difflib.unified_diff(text.splitlines(True),rewritten.splitlines(True),fromfile=str(original),tofile=str(override))))
    (proof/'overlay.json').write_text(json.dumps({'Replace':{str(original):str(override)}},indent=2)+'\n')
    def owner(symbol):
        found=[p.parent.relative_to(output).as_posix() for p,text in sources.items() if f'func {symbol}(' in text]
        assert len(found)==1,(symbol,found)
        return found[0]
    names={'take':'StringTakeCodePointsUnicode1500','concat':'StringConcat1000','split':'StringSplit1000'}
    owners={kind:owner(f'Get_Test_{name}_prepare') for kind,name in names.items()}
    checksum_owner=owner('Get_Bench_StringFixtures_checksum');ffi_owner=owner('Data_String_CodePoints__ToCodePointArray');split_owner=owner('Data_String_Common_Split')
    boundary=original.parent.relative_to(output).as_posix()
    aliases={p:f'p{i}' for i,p in enumerate(sorted(set(owners.values())|{checksum_owner,ffi_owner,split_owner,boundary}))}
    imports='\n'.join(f'{alias} "gopurs/output/{p}"' for p,alias in aliases.items())
    factories=','.join(f'"{kind}":{aliases[owners[kind]]}.Get_Test_{name}_prepare' for kind,name in names.items())
    adapter=callback_adapter(sources)
    program=r'''package main
import("encoding/hex";"encoding/json";"fmt";"os";r "gopurs/output/gopurs_runtime"
IMPORTS
)
type Input struct {ID int `json:"id"`;Kind string `json:"kind"`;Domain string `json:"domain"`;TextHex string `json:"text_hex"`;Count int64 `json:"count"`;Fragments []string `json:"fragments"`;SeparatorHex string `json:"separator_hex"`}
func bytesString(value string)string{raw,e:=hex.DecodeString(value);if e!=nil{panic(e)};return string(raw)}
func referenceChecksum(s string)int64{total:=int64(0);for _,cp:=range FFI.Data_String_CodePoints__ToCodePointArray(nil,nil,s){total=int64(int32(total+cp))};return total}
func reference(input Input)int64{
 s:=bytesString(input.TextHex)
 switch input.Kind{
 case "checksum":return referenceChecksum(s)
 case "take":return referenceChecksum(FFI.Data_String_CodePoints__Take(nil,input.Count,s))
 case "concat":for _,part:=range input.Fragments{s+=bytesString(part)};return referenceChecksum(s)
 case "split":parts:=SPLIT.Data_String_Common_Split(bytesString(input.SeparatorHex),s);total:=int64(len(parts));for _,part:=range parts{total=int64(int32(total+referenceChecksum(part)))};return total
 };panic("unknown kind")
}
func main(){
 var inputs []Input;f,e:=os.Open(os.Args[1]);if e!=nil{panic(e)};if e=json.NewDecoder(f).Decode(&inputs);e!=nil{panic(e)}
 refs,e:=os.Create(os.Args[2]);if e!=nil{panic(e)};defer refs.Close()
 factories:=map[string]func()r.Value{FACTORIES};actions:=map[string]r.Value{}
 for kind,factory:=range factories{BOUNDARY.StringChecksumAuditInputs=[]interface{}{r.Int(17),nil};BOUNDARY.StringChecksumAuditCalls=0;actions[kind]=r.Apply(factory(),r.Value{});if BOUNDARY.StringChecksumAuditCalls!=2{panic("incorrect preparation opacity")}}
 for _,input:=range inputs{
  str:=bytesString(input.TextHex);boxed:=r.Str(str)
  fragments:=make([]r.Value,len(input.Fragments));for i,raw:=range input.Fragments{fragments[i]=r.Str(bytesString(raw))};array:=r.Array(fragments)
  expected:=reference(input);fmt.Fprintf(refs,"%d %d\n",input.ID,expected)
  for _,path:=range []string{"Apply","ffi_conversion","forced_fallback"}{
   BOUNDARY.StringChecksumAuditInputs=[]interface{}{boxed}
   if input.Kind=="take"{BOUNDARY.StringChecksumAuditInputs=append(BOUNDARY.StringChecksumAuditInputs,r.Int(input.Count))}
   if input.Kind=="split"{BOUNDARY.StringChecksumAuditInputs=append(BOUNDARY.StringChecksumAuditInputs,r.Str(bytesString(input.SeparatorHex)))}
   if input.Kind=="concat"{BOUNDARY.StringChecksumAuditInputs=[]interface{}{array}}
   BOUNDARY.StringChecksumAuditCalls=0
   var action r.Value
   if input.Kind=="checksum"{action=r.Func(func(_ r.Value)r.Value{return r.Apply(CHECKSUM.Get_Bench_StringFixtures_checksum(),boxed)});BOUNDARY.StringChecksumAuditInputs=nil}else{action=actions[input.Kind]}
   var actual int64
   if path=="Apply"{v:=r.Apply(action,r.Value{});if v.Type!=r.TypeInt{panic("not an Int")};actual=v.IntVal}else{selected:=action;if path=="forced_fallback"{selected=r.Func(func(_ r.Value)r.Value{return r.Apply(action,r.Value{})})};actual=int64(convertCallback(selected)())}
   if actual!=expected{panic(fmt.Sprintf("reference mismatch %d %s got %d expected %d",input.ID,path,actual,expected))}
   if BOUNDARY.StringChecksumAuditCalls!=len(BOUNDARY.StringChecksumAuditInputs){panic("incorrect per-invocation opacity")}
   if boxed.StrVal()!=str{panic("input string changed")};for i,v:=range fragments{if v.StrVal()!=bytesString(input.Fragments[i]){panic("input fragment changed")}}
   fmt.Printf("%d %s %d\n",input.ID,path,actual)
  }
 }
}
'''.replace('IMPORTS',imports).replace('FACTORIES',factories).replace('BOUNDARY',aliases[boundary]).replace('CHECKSUM',aliases[checksum_owner]).replace('FFI',aliases[ffi_owner]).replace('SPLIT',aliases[split_owner])+adapter['source']
    (proof/'main.go').write_text(program)
    oracle=r'''import fs from 'node:fs';
const rows=JSON.parse(fs.readFileSync(process.argv[2],'utf8'));
const text=units=>{let s='';for(const unit of units)s+=String.fromCharCode(unit);return s;};
